import { useEffect, useState } from 'preact/hooks';
import { isLocallyAdministered, normalizeMac } from './mac';
import { TABLE as SAMPLE } from './ouiSample';

// MAC vendor lookup from OUI tables generated by scripts/build-oui.mjs from
// the IEEE MA-L registry, home and consumer makers only. The entry chunk
// carries a small sample (ouiSample.ts); every prefix of those makers is in
// ouiFull.ts, a lazy chunk the Clients page loads (useFullOuiTable). Phones
// mostly use private addresses, which no table can name; client names fill
// the gap in model/clients.ts. Format: see the script.

export type DeviceKind = 'phone' | 'computer' | 'tv' | 'console' | 'speaker' | 'iot' | 'camera' | 'printer' | 'network' | 'nas';

const KIND: Record<string, DeviceKind> = {
  p: 'phone',
  c: 'computer',
  t: 'tv',
  g: 'console',
  s: 'speaker',
  i: 'iot',
  v: 'camera',
  r: 'printer',
  n: 'network',
  d: 'nas',
};

const FINAL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ!#$%&*';

export interface Vendor {
  name: string;
  kind?: DeviceKind;
}

let sample: Map<number, Vendor> | undefined;
let full: Map<number, Vendor> | undefined;
let loading: Promise<void> | undefined;

function build(table: string): Map<number, Vendor> {
  const m = new Map<number, Vendor>();
  for (const group of table.split('|')) {
    const [head, body = ''] = group.split(':');
    const [name = '', k] = head!.split('/');
    const v: Vendor = { name, kind: k ? KIND[k] : undefined };
    let oui = 0;
    let acc = 0;
    for (const ch of body) {
      const f = FINAL.indexOf(ch);
      if (f < 0) {
        acc = acc * 32 + parseInt(ch, 32);
        continue;
      }
      oui += acc * 32 + f;
      acc = 0;
      m.set(oui, v);
    }
  }
  return m;
}

/** Vendor for a globally unique MAC, if it is in the table. */
export function ouiVendor(mac: string): Vendor | undefined {
  const n = normalizeMac(mac);
  if (!n || isLocallyAdministered(n)) return undefined;
  const index = full ?? (sample ??= build(SAMPLE));
  return index.get(parseInt(n.slice(0, 8).replace(/:/g, ''), 16));
}

/** What the Vendor column shows: the maker, "Private address" for a randomized MAC, or nothing. */
export function vendorLabel(mac: string): string | undefined {
  return isLocallyAdministered(mac) ? 'Private address' : ouiVendor(mac)?.name;
}

/** Loads the full table once; lookups use it from then on. */
export function loadFullOuiTable(): Promise<void> {
  loading ??= import('./ouiFull').then(
    (m) => void (full = build(m.TABLE)),
    () => void (loading = undefined), // Offline or a stale deploy: keep the sample, try again next time.
  );
  return loading;
}

/** Loads the full table and re-renders the caller once it is in. */
export function useFullOuiTable(): void {
  const [, setLoaded] = useState(!!full);
  useEffect(() => {
    if (!full) void loadFullOuiTable().then(() => setLoaded(!!full));
  }, []);
}
